using System.Diagnostics; using CertDesk.Common; using CertDesk.Models; using CertDesk.Services;
namespace CertDesk.Views;
public partial class ReportsView:UserControl{ readonly CurrentUser u; ComboBox type=new(){Width=360,DropDownStyle=ComboBoxStyle.DropDownList}; DateTimePicker from=new(),to=new(); Label last=new(){AutoSize=true,Top=170,Left=20,Width=800}; public ReportsView(CurrentUser user){u=user;InitializeComponent();Build();} void Build(){BackColor=UiTheme.Light; Controls.AddRange(new Control[]{new Label{Text="Тип отчета",Left=20,Top=25},type,new Label{Text="Период с",Left=20,Top=70},from,new Label{Text="по",Left=310,Top=70},to,last}); type.Left=130;type.Top=20; from.Left=130;from.Top=65;to.Left=340;to.Top=65; from.Value=DateTime.Today.AddMonths(-1); foreach(var r in ReportService.ReportTypes) type.Items.Add(r); type.SelectedIndex=0; var csv=B("Экспорт CSV",20,115), xlsx=B("Экспорт XLSX",150,115), open=B("Открыть папку отчетов",285,115); Controls.AddRange(new Control[]{csv,xlsx,open}); csv.Click+=(_,__)=>Export(false); xlsx.Click+=(_,__)=>Export(true); open.Click+=(_,__)=>Process.Start(new ProcessStartInfo{FileName=ReportService.OutputDirectory,UseShellExecute=true});} Button B(string t,int x,int y){var b=new Button{Text=t,Left=x,Top=y,Width=120};UiTheme.ApplyButtonStyle(b);return b;} void Export(bool x){try{var p=x?ReportService.ExportXlsx(type.Text,from.Value,to.Value,u):ReportService.ExportCsv(type.Text,from.Value,to.Value,u);last.Text="Последний файл: "+p;MessageHelper.Info("Отчет сохранен:\n"+p);}catch(Exception ex){MessageHelper.Error(ex.Message);}} }
